CREATE FUNCTION public.pl_item_volume(p_qty numeric,p_l numeric,p_w numeric,p_h numeric,p_manual numeric) RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path=public AS $$select case when coalesce(p_l,0)>0 and coalesce(p_w,0)>0 and coalesce(p_h,0)>0 then round(p_l*p_w*p_h/1000000.0*p_qty,4) else round(greatest(coalesce(p_manual,0),0),4) end$$;
CREATE FUNCTION public.pl_actor_name() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$select coalesce(nullif(trim(p.full_name),''),nullif(p.email,''),'Pengguna') from public.profiles p where p.id=auth.uid()$$;
CREATE FUNCTION public.pl_before_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$declare note text:=nullif(trim(coalesce(current_setting('pl.status_note',true),'')),'');begin if tg_op='INSERT' then if new.pl_number is null or char_length(trim(new.pl_number))=0 then new.pl_number:='PL-'||to_char(coalesce(new.pl_date,current_date),'YYYYMM')||'-'||lpad(nextval('public.pl_number_seq')::text,5,'0');end if;new.status_changed_at:=now();new.status_changed_by:=auth.uid();elsif new.status is distinct from old.status then if new.status='dibatalkan' and(note is null or char_length(note)<5) then raise exception 'Alasan pembatalan wajib diisi (minimal 5 karakter)';end if;new.status_changed_at:=now();new.status_changed_by:=auth.uid();else new.status_changed_at:=old.status_changed_at;new.status_changed_by:=old.status_changed_by;end if;new.updated_at:=now();return new;end$$;
CREATE FUNCTION public.pl_after_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$begin if tg_op='INSERT' or new.status is distinct from old.status then insert into public.pl_status_history(packing_list_id,from_status,to_status,note,changed_by,changed_by_name,changed_at) values(new.id,case when tg_op='UPDATE' then old.status end,new.status,nullif(trim(coalesce(current_setting('pl.status_note',true),'')),''),auth.uid(),public.pl_actor_name(),new.status_changed_at);end if;return null;end$$;
CREATE FUNCTION public.pl_log_activity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$declare r jsonb;label text;act text;ent text;plid uuid;begin r:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;act:=case tg_op when 'INSERT' then 'create' when 'UPDATE' then 'update' else 'delete' end;ent:=case tg_table_name when 'pl_parties' then r->>'kind' when 'pl_vessels' then 'kapal' when 'pl_ports' then 'pelabuhan' else 'packing_list' end;label:=coalesce(r->>'pl_number',r->>'name','-');if tg_table_name='pl_packing_lists' then plid:=(r->>'id')::uuid;if tg_op='UPDATE' and new.status is distinct from old.status and(to_jsonb(new)-array['status','status_changed_at','status_changed_by','updated_at','updated_by'])=(to_jsonb(old)-array['status','status_changed_at','status_changed_by','updated_at','updated_by']) then act:='status';end if;end if;insert into public.pl_activity_logs(packing_list_id,entity,entity_id,action,summary,details,actor_id,actor_name) values(plid,ent,(r->>'id')::uuid,act,label,case when tg_op='UPDATE' then jsonb_build_object('before',to_jsonb(old),'after',to_jsonb(new)) when tg_op='DELETE' then jsonb_build_object('before',to_jsonb(old)) else jsonb_build_object('after',to_jsonb(new)) end||case when act='status' then jsonb_build_object('note',nullif(trim(coalesce(current_setting('pl.status_note',true),'')),'')) else '{}'::jsonb end,auth.uid(),public.pl_actor_name());return null;end$$;
create trigger trg_pl_lists_before before insert or update on public.pl_packing_lists for each row execute function public.pl_before_write();create trigger trg_pl_lists_status after insert or update on public.pl_packing_lists for each row execute function public.pl_after_status();create trigger trg_pl_lists_log after insert or update or delete on public.pl_packing_lists for each row execute function public.pl_log_activity();create trigger trg_pl_parties_log after insert or update or delete on public.pl_parties for each row execute function public.pl_log_activity();create trigger trg_pl_vessels_log after insert or update or delete on public.pl_vessels for each row execute function public.pl_log_activity();create trigger trg_pl_ports_log after insert or update or delete on public.pl_ports for each row execute function public.pl_log_activity();
CREATE FUNCTION public.save_packing_list(p_id uuid,p_header jsonb,p_items jsonb) RETURNS public.pl_packing_lists LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$declare rec public.pl_packing_lists;n int;t_koli numeric;t_w numeric;t_v numeric;t_val numeric;begin if not public.is_staff() then raise exception 'Tidak memiliki akses Packing List';end if;if p_items is null or jsonb_typeof(p_items)<>'array' then raise exception 'Daftar barang tidak valid';end if;n:=jsonb_array_length(p_items);if n=0 then raise exception 'Minimal satu barang wajib diisi';end if;if n>500 then raise exception 'Maksimal 500 barang per packing list';end if;if nullif(p_header->>'shipper_id','') is null then raise exception 'Pengirim wajib dipilih';end if;if nullif(p_header->>'consignee_id','') is null then raise exception 'Penerima wajib dipilih';end if;if exists(select 1 from jsonb_array_elements(p_items) i where char_length(trim(coalesce(i->>'name','')))=0) then raise exception 'Nama barang wajib diisi';end if;if exists(select 1 from jsonb_array_elements(p_items) i where coalesce((i->>'qty')::numeric,0)<=0) then raise exception 'Jumlah barang harus lebih dari 0';end if;
select coalesce(sum((i->>'qty')::numeric),0),coalesce(sum((i->>'qty')::numeric*coalesce(nullif(i->>'weight_kg','')::numeric,0)),0),coalesce(sum(public.pl_item_volume((i->>'qty')::numeric,nullif(i->>'length_cm','')::numeric,nullif(i->>'width_cm','')::numeric,nullif(i->>'height_cm','')::numeric,nullif(i->>'volume_m3','')::numeric)),0),coalesce(sum(coalesce(nullif(i->>'value_idr','')::numeric,0)),0) into t_koli,t_w,t_v,t_val from jsonb_array_elements(p_items) i;
if p_id is null then insert into public.pl_packing_lists(pl_date,shipper_id,consignee_id,vessel_id,voyage_no,origin_port_id,destination_port_id,container_no,seal_no,etd,eta,notes,total_koli,total_weight_kg,total_volume_m3,total_value,item_count,created_by,updated_by) values(coalesce(nullif(p_header->>'pl_date','')::date,current_date),(p_header->>'shipper_id')::uuid,(p_header->>'consignee_id')::uuid,nullif(p_header->>'vessel_id','')::uuid,nullif(trim(coalesce(p_header->>'voyage_no','')),''),nullif(p_header->>'origin_port_id','')::uuid,nullif(p_header->>'destination_port_id','')::uuid,nullif(trim(coalesce(p_header->>'container_no','')),''),nullif(trim(coalesce(p_header->>'seal_no','')),''),nullif(p_header->>'etd','')::date,nullif(p_header->>'eta','')::date,nullif(trim(coalesce(p_header->>'notes','')),''),t_koli,round(t_w,2),round(t_v,4),round(t_val,2),n,auth.uid(),auth.uid()) returning * into rec;
else perform 1 from public.pl_packing_lists where id=p_id for update;if not found then raise exception 'Packing list tidak ditemukan';end if;update public.pl_packing_lists set pl_date=coalesce(nullif(p_header->>'pl_date','')::date,pl_date),shipper_id=(p_header->>'shipper_id')::uuid,consignee_id=(p_header->>'consignee_id')::uuid,vessel_id=nullif(p_header->>'vessel_id','')::uuid,voyage_no=nullif(trim(coalesce(p_header->>'voyage_no','')),''),origin_port_id=nullif(p_header->>'origin_port_id','')::uuid,destination_port_id=nullif(p_header->>'destination_port_id','')::uuid,container_no=nullif(trim(coalesce(p_header->>'container_no','')),''),seal_no=nullif(trim(coalesce(p_header->>'seal_no','')),''),etd=nullif(p_header->>'etd','')::date,eta=nullif(p_header->>'eta','')::date,notes=nullif(trim(coalesce(p_header->>'notes','')),''),total_koli=t_koli,total_weight_kg=round(t_w,2),total_volume_m3=round(t_v,4),total_value=round(t_val,2),item_count=n,updated_by=auth.uid() where id=p_id returning * into rec;delete from public.pl_items where packing_list_id=p_id;end if;
insert into public.pl_items(packing_list_id,line_no,name,qty,unit,weight_kg,length_cm,width_cm,height_cm,volume_m3,value_idr,notes,condition) select rec.id,x.ord::int,left(trim(x.i->>'name'),200),(x.i->>'qty')::numeric,coalesce(nullif(x.i->>'unit',''),'koli'),round(coalesce(nullif(x.i->>'weight_kg','')::numeric,0),2),nullif(x.i->>'length_cm','')::numeric,nullif(x.i->>'width_cm','')::numeric,nullif(x.i->>'height_cm','')::numeric,public.pl_item_volume((x.i->>'qty')::numeric,nullif(x.i->>'length_cm','')::numeric,nullif(x.i->>'width_cm','')::numeric,nullif(x.i->>'height_cm','')::numeric,nullif(x.i->>'volume_m3','')::numeric),nullif(x.i->>'value_idr','')::numeric,nullif(left(trim(coalesce(x.i->>'notes','')),500),''),coalesce(nullif(x.i->>'condition',''),'baik') from jsonb_array_elements(p_items) with ordinality as x(i,ord);return rec;end$$;
CREATE FUNCTION public.set_packing_list_status(p_id uuid,p_status public.pl_status,p_note text) RETURNS public.pl_packing_lists LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$declare rec public.pl_packing_lists;begin if not public.is_staff() then raise exception 'Tidak memiliki akses Packing List';end if;perform set_config('pl.status_note',left(coalesce(p_note,''),500),true);update public.pl_packing_lists set status=p_status,updated_by=auth.uid() where id=p_id returning * into rec;if not found then raise exception 'Packing list tidak ditemukan';end if;perform set_config('pl.status_note','',true);return rec;end$$;
revoke all on function public.save_packing_list(uuid,jsonb,jsonb),public.set_packing_list_status(uuid,public.pl_status,text),public.pl_actor_name(),public.pl_before_write(),public.pl_after_status(),public.pl_log_activity() from public,anon;
grant execute on function public.save_packing_list(uuid,jsonb,jsonb),public.set_packing_list_status(uuid,public.pl_status,text),public.pl_actor_name() to authenticated,service_role;
create function public.setup_status() returns boolean language sql stable security definer set search_path=public as $$select not exists(select 1 from public.user_roles where role='super_admin')$$;
revoke all on function public.setup_status() from public;grant execute on function public.setup_status() to anon,authenticated,service_role;
create function public.claim_initial_admin() returns void language plpgsql security definer set search_path=public as $$begin perform pg_advisory_xact_lock(hashtext('initial_admin'));if auth.uid() is null or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'Verifikasi email terlebih dahulu';end if;if exists(select 1 from public.user_roles where role='super_admin') then raise exception 'Penyiapan awal ditutup';end if;insert into public.user_roles(user_id,role) values(auth.uid(),'super_admin');end$$;
revoke all on function public.claim_initial_admin() from public,anon;grant execute on function public.claim_initial_admin() to authenticated;
create function public.set_managed_role(p_user_id uuid,p_role public.app_role) returns void language plpgsql security definer set search_path=public as $$begin if not public.has_role(auth.uid(),'super_admin') then raise exception 'Hanya Super Admin';end if;if p_user_id=auth.uid() and not public.has_role(p_user_id,p_role) then raise exception 'Anda tidak dapat mengubah peran akun sendiri';end if;insert into public.user_roles(user_id,role) values(p_user_id,p_role) on conflict(user_id) do update set role=excluded.role;end$$;
revoke all on function public.set_managed_role(uuid,public.app_role) from public,anon;grant execute on function public.set_managed_role(uuid,public.app_role) to authenticated;